import type { CourseSource, GuidedCourse } from '../../courses';

/**
 * English edition of "Dönüm Noktası Günü" (turning-day). Lesson IDs, practice
 * counts and answer positions match the Turkish edition. Sources translated
 * here keep their Turkish-edition ids. 'mental-practice' and
 * 'dispenza-breaking-habit' (meditation) and 'murphy-subconscious'
 * (suggestion) are cited with their shared ids and translated in those
 * courses' files. New source (Sep 2026): 'turning-day-commitment-contract'.
 */
export const SOURCES: CourseSource[] = [
  { id: 'fresh-start-effect', title: 'Dai, Milkman & Riis · 2014 · The fresh-start effect', url: 'https://faculty.wharton.upenn.edu/wp-content/uploads/2014/06/Dai_Fresh_Start_2014_Mgmt_Sci.pdf', type: 'research', finding: 'Across three sets of field data, goal-directed behavior rose at the start of new time periods: Google searches for “diet” rose 14.4% at the start of a week and 82.1% at the start of a year; gym visits by 11,912 university students rose 33.4% at the start of a week and 47.1% at the start of a semester; new goal commitments on the stickK website rose 62.9% at the start of a week and 145.3% at the start of a year.', limitation: 'Observational field data that do not test the mechanism directly; they mostly look at shared calendar landmarks and do not show how long the extra drive lasts. The authors note that the rise after public holidays faded quickly.' },
  { id: 'fresh-start-framing', title: 'Dai, Milkman & Riis · 2015 · Temporal landmarks and goal initiation experiments', url: 'https://anderson-review.ucla.edu/wp-content/uploads/2021/03/Dai-Milkman-Riis_2015_TemporalLandmarks_APS_0956797615605818.pdf', type: 'research', finding: 'In five experiments, framing a day as a fresh start increased the wish to begin on a goal: among 165 participants, 25.6% chose a goal reminder for March 20 when it was presented as “the first day of spring,” versus 7.2% when it was called “the third Thursday in March.” The effect was explained by feeling psychologically distant from one’s past, imperfect self.', limitation: 'Short experiments with online participants; the measures are mostly intentions, reminder choices and hypothetical scenarios. They do not show real, lasting behavior change.' },
  { id: 'bandura-self-efficacy', title: 'Bandura · 1977 · The theory of self-efficacy', url: 'https://eric.ed.gov/?id=EJ161632', type: 'research', finding: 'Bandura proposes that psychological change works through self-efficacy, the expectation that you can carry out a behavior, and names four sources of that expectation: mastery experiences, watching others (vicarious experience), verbal persuasion and physiological state. He treats mastery experiences as the most powerful source because they rest on personal accomplishment, and writes that a belief strengthened by repeated success is less shaken by occasional failure.', limitation: 'A theoretical article in Psychological Review; it reports no new experiment or effect size and draws largely on fear-treatment studies of its time.' },
  { id: 'self-efficacy-work-meta', title: 'Stajkovic & Luthans · 1998 · Meta-analysis of self-efficacy and work performance', url: 'https://doi.org/10.1037/0033-2909.124.2.240', type: 'research', finding: 'A meta-analysis pooling 114 studies (157 effect sizes, 21,616 people) found a significant, moderate relationship between self-efficacy and work performance (weighted average r = 0.38).', limitation: 'Abstract only. A correlational finding; on its own it does not show how far self-efficacy causes performance, and it comes from work tasks.' },
  { id: 'todo-list-bedtime', title: 'Scullin et al. · 2018 · Writing a to-do list before bed and falling asleep', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5758411/', type: 'research', finding: 'In a sleep lab, 57 healthy young adults aged 18–30 spent 5 minutes before bed writing either the tasks they needed to do in the coming days or the tasks they had completed in recent days. Those who wrote a to-do list fell asleep faster, and the more specific the list, the faster they fell asleep.', limitation: 'A single lab night with a small, young sample; it does not show whether the same happens for people with insomnia or over the long term. Abstract only.' },
  { id: 'franklin-daily-questions', title: 'Benjamin Franklin · Autobiography · Morning and evening questions', url: 'https://www.gutenberg.org/ebooks/20203', type: 'technique', finding: 'As part of his plan for tracking his virtues, Franklin describes a schedule that organizes his day hour by hour: on rising and planning the day’s business he asks, “What good shall I do this day?”, and when reviewing the day in the evening, “What good have I done today?”', limitation: 'A public-domain, historical first-person account; not a scientifically tested method.' },
  { id: 'oettingen-woop-method', title: 'Gabriele Oettingen · WOOP · Rethinking Positive Thinking (2014)', url: 'https://woopmylife.org/en/home', type: 'technique', finding: 'Oettingen’s WOOP method has four steps: Wish, Outcome, Obstacle, Plan. Instead of only dreaming positively, it asks you to contrast the outcome you want with the real obstacle in your way and to make an if–then plan for that obstacle.', limitation: 'The mental contrasting and if–then planning the method rests on showed small-to-medium average effects in research; the official site belongs to the method’s developers and is not an independent evaluation.' },
  { id: 'clear-two-minute-rule', title: 'James Clear · The two-minute rule · Atomic Habits (2018)', url: 'https://jamesclear.com/how-to-stop-procrastinating', type: 'technique', finding: 'The rule has two parts: David Allen’s advice to do at once anything that takes less than two minutes, and Clear’s adaptation that a new habit should start with a first step that takes less than two minutes, for example reading one page instead of reading for an hour.', limitation: 'A practical suggestion; the rule itself has not been tested directly in controlled studies.' },
  { id: 'fogg-anchor-recipe', title: 'BJ Fogg · Tiny Habits (2019)', url: 'https://tinyhabits.com/', type: 'technique', finding: 'Fogg, who directs the Behavior Design Lab at Stanford, suggests making a new behavior very small, attaching it right after an “anchor” you already do every day, and celebrating briefly as soon as you have done it.', limitation: 'Consistent with findings that repetition in the same context strengthens habits, but the method itself, especially the celebration step, has had limited testing in independent randomized studies.' },
  { id: 'seinfeld-chain-story', title: '“Don’t break the chain,” attributed to Jerry Seinfeld · as told by James Clear', url: 'https://jamesclear.com/stop-procrastinating-seinfeld-strategy', type: 'technique', finding: 'In the story, you put a big X on a wall calendar for each day you do the work, and the goal is not to break the chain that forms, shifting attention from any single day’s result to consistency.', limitation: 'An anecdote the comedian Brad Isaac told Lifehacker; according to Clear’s note, Seinfeld has said the idea was not his and that he did not claim to use it. The method has not been tested directly.' },
  { id: 'habits', title: 'Lally et al. · 2010 · Habit formation in everyday life', url: 'https://onlinelibrary.wiley.com/doi/10.1002/ejsp.674', type: 'research', finding: 'Following 96 volunteers for 12 weeks, the study tracked repetition in the same context and growing automaticity; the time it took varied widely between people, and missing a behavior once did not noticeably affect the habit-forming process.', limitation: 'An observational study based on self-report; it gives no fixed number of days that holds for everyone. The publisher’s abstract was read.' },
  { id: 'turning-day-commitment-contract', title: 'Giné, Karlan & Zinman · 2010 · A commitment contract for quitting smoking', url: 'https://www.aeaweb.org/articles?id=10.1257%2Fapp.2.4.213', type: 'research', finding: 'Smokers were offered a savings account: they deposited money for six months and then took a urine test for nicotine and cotinine. If they passed, the money was returned; if not, it went to charity. 11% of those offered the account signed up. Smokers randomly offered it were 3 percentage points more likely to pass the six-month test, and the difference held in surprise tests at 12 months.', limitation: 'Abstract only. One field experiment on one behavior (smoking); take-up was low and the average effect small. It shows that a commitment device can help some people, not that it suits everyone.' },
];

export const COURSE: GuidedCourse = {
  id: 'turning-day', title: 'Turning Point Day', subtitle: 'One day, the first evidence.',
  description: 'Turn a single day into a real beginning in five short sessions: choose a direction, plan for the obstacle, take the first small step, and turn it into evidence over the next 7 days. Confidence grows from small proof like this.',
  scope: 'Personal growth training for adults. It is not therapy, diagnosis or treatment, and it does not promise that your life will change in a single day. Do not stop any treatment or medication without talking to your doctor. If you are dealing with intense anxiety, low mood or distress that makes daily life hard, please see a health professional; if you have thoughts of harming yourself or are in immediate danger, call your local emergency number.',
  outcome: 'An area you chose and your reason for it, an if–then plan, a first small step taken today, a prepared environment, one supporter, a written evidence note and a 7-day follow-up plan.',
  photo: { id: '1570821805833-1103c43f9c1d', alt: 'Sunbeams falling across a path between trees' },
  lessons: [
    { id: 'turning-day-1', title: 'Morning · Direction: mark today as a beginning', minutes: 7,
      goal: 'This morning, mark today as a fresh start and choose one area of life plus a reason that matters to you.',
      reading: ['In 2014, Dai, Milkman and Riis showed that people turn toward their goals more at the start of a new period. Google searches for “diet” rose 14.4% at the start of a week and 82.1% at the start of a year; university gym visits rose 33.4% at the start of a week and 47.1% at the start of a semester. The researchers called this the fresh-start effect. But these are observational data and do not show how long the new drive lasts; the rise after public holidays faded quickly.', 'In 2015 the same team found that the way a day is named matters too. When March 20 was presented as “the first day of spring,” 25.6% of participants chose a goal reminder for that day; when it was called “the third Thursday in March,” only 7.2% did. So you do not have to wait for the calendar to hand you a special day; you can mark today yourself. These experiments mostly measured intention, though. One day does not change a life; small steps repeated over the next days turn it into evidence. So the morning’s job is not a big promise, but one area and a strong reason.'],
      practice: ['Write today’s date and next to it the words “My starting day.”', 'From areas like health, relationships, work or learning, choose only one for today.', 'Write why this area matters in one sentence, “Because … matters to me,” and add it to the Today screen in the app as the day’s one decision.'],
      reflection: 'When you marked today as a beginning, what changed inside you, and what stayed the same?',
      question: 'What does research on the fresh-start effect show?',
      options: ['The wish to work on a goal can rise at the start of a new period; whether it lasts depends on the steps that follow.', 'A Monday or a new year guarantees that you reach your goal on its own.', 'You must wait for a special day on the calendar before you can begin.'], correct: 0,
      feedback: 'Time landmarks can raise the wish to begin, and you can mark today as a landmark yourself. But that wish was also seen to fade fast; what makes it last is small repetition over the following days.',
      takeaway: 'Today can be a beginning; the following days bring the proof.',
      sources: ['fresh-start-effect', 'fresh-start-framing', 'franklin-daily-questions', 'dispenza-breaking-habit', 'mental-practice'],
      visual: { kind: 'bars', title: 'Same day, different name: who chose a reminder',
        bars: [
          { label: 'Presented as “the first day of spring”', value: 25.61, display: '25.6%' },
          { label: 'Presented as “the third Thursday in March”', value: 7.23, display: '7.2%' },
        ],
        note: 'Share of 165 online participants who chose a goal reminder for March 20 (Dai, Milkman and Riis 2015, study 1a). It measures intention and reminder choice, not lasting behavior change.',
        sourceId: 'fresh-start-framing' },
      deeper: [
        { heading: 'Why a fresh start works', paragraphs: [
          'Dai, Milkman and Riis explain the effect this way: a time landmark, such as a new week, a new year or a day you choose to mark, draws a line between the past and the present. The mistakes of the “old you” feel a little further away, so trying again feels less like repeating a failure and more like opening a new chapter. In their experiments, the very same date drew more goal reminders when it was framed as a beginning.',
          'The same research also shows the weak point: the lift is real but short. Think of it as a wave that helps you push off, not as a current that carries you. That is why this course asks you to use today’s energy for something small and concrete, and then to repeat it tomorrow.',
        ],
          visual: { kind: 'compare', title: 'Waiting for a landmark or making one',
            left: { label: 'Waiting for Monday', items: ['“I’ll start properly next week.”', 'The drive builds up, then fades before it is used.', 'A missed day means waiting for the next Monday.'] },
            right: { label: 'Marking today', items: ['“Today is my starting day.”', 'The drive is spent on one small, real step.', 'A missed day means starting again tomorrow morning.'] },
            note: 'Framing a day as a fresh start raised the wish to begin in experiments; how long it lasts depends on what you do next.' } },
        { heading: 'Common mistakes on a starting day', paragraphs: [
          'The first is choosing everything at once: a new diet, a new exercise plan and a new work routine on the same morning. Several changes compete for the same limited energy, and when one slips, all of them can feel lost. One area is enough for one day.',
          'The second is picking an area because it sounds impressive rather than because it matters to you. A reason that is truly yours (“because I want to keep up with my kids on a walk”) tends to hold up better on a tired afternoon than a borrowed one (“because everyone says I should”). If your reason feels flat when you say it out loud, keep looking for a moment longer.',
        ] },
      ],
      example: { title: 'Dana, 34, nurse on rotating shifts', text: 'Dana had been “starting on Monday” for months, but her shifts meant Monday was often a night shift. On a Wednesday off, she wrote the date in her notebook with the words “My starting day” next to it. She felt a bit silly. From the long list in her head (sleep, cooking, money, calling her sister) she picked just one: movement. Her reason took a few tries: “Because I want my back to stop aching after a twelve-hour shift.” That one felt true. She added it to her phone as the day’s one decision and did nothing else dramatic. The day did not feel like a turning point yet. But when a colleague asked about her plans, she could name one area and a reason in a single sentence, and that was new.' },
      technique: { name: 'The morning question and a “who am I choosing to be today?” rehearsal',
        origin: 'Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012); morning question: Benjamin Franklin’s daily scheme',
        steps: [
          'When you wake up, before looking at your phone, sit quietly for 3–5 minutes and take a few slow breaths.',
          'Ask yourself Franklin’s morning question: “What good shall I do this day?”',
          'Notice one old reaction you want to leave behind today and give it a name, such as “the me who puts things off.”',
          'Ask, “Who am I choosing to be today?” and answer with a single quality: calm, brave or organized.',
          'Picture one moment of the day in that state: where you are, what you are doing and how it feels.',
          'When you open your eyes, choose one small action from this rehearsal that you will do today, and write it down.',
        ],
        evidence: 'Mental rehearsal can help you prepare for a behavior, especially when it is combined with a real plan. The book’s claims of changing reality through quantum physics or healing illness with thought are not supported by science; place the rehearsal before action, not in place of it.',
        sourceId: 'dispenza-breaking-habit' },
      photo: { id: '1676475382103-54041209cf6c', alt: 'Woman writing notes in a notebook beside a coffee cup' } },
    { id: 'turning-day-2', title: 'Midday · See the obstacle, build an if–then plan', minutes: 8,
      goal: 'At midday, find a realistic inner obstacle for the area you chose this morning and write an if–then plan for it.',
      reading: ['Psychologist Gabriele Oettingen argues that only picturing the happy outcome can relax you and drain the energy you need to act. Her suggestion is to look, right after imagining the outcome you want, at the real obstacle in your way; this is called mental contrasting. In a meta-analysis by Wang, Wang and Gai covering 21 studies and 15,907 participants, this contrasting, combined with an if–then plan, showed a small-to-medium average effect on reaching goals. Publication bias is possible, and results vary from person to person.', 'An if–then plan means writing down in advance when and where the obstacle will show up, together with your answer: “If I feel tired in the afternoon, then I will do just the two-minute part.” In Gollwitzer and Sheeran’s meta-analysis of 94 tests, plans like this showed a medium-to-large effect on reaching goals (d = 0.65); analyses that correct for publication bias may shrink that number. The obstacle is often inside rather than outside: tiredness, embarrassment or the thought “I’ll do it later.” Naming it in advance means the moment will not catch you unprepared.'],
      practice: ['On a short walk or during your lunch break, say your wish for this morning’s area in one sentence.', 'Name the inner obstacle most likely to stop you today, such as tiredness, embarrassment or the thought of putting it off.', 'Complete the sentence “If … happens, then I will …” and save it somewhere on your phone you can find easily.'],
      reflection: 'Which inner voice is most likely to stop you today, and what is your ready answer to it?',
      question: 'In WOOP, which step comes after imagining the best outcome?',
      options: ['Imagining the outcome in even more detail and never thinking about obstacles.', 'Finding the real inner obstacle in your way and writing a plan for it.', 'Telling no one about the goal so that no obstacle appears.'], correct: 1,
      feedback: 'In WOOP, the imagined outcome is followed by finding the main inner obstacle and writing an if–then plan for it. Together they showed a small-to-medium average effect in a meta-analysis; not a guarantee, but a way of being prepared.',
      takeaway: 'The dream gives direction; the obstacle plan clears the way.',
      sources: ['mcii', 'if-then-plans', 'oettingen-woop-method', 'turning-day-commitment-contract', 'fresh-start-effect'],
      visual: { kind: 'compare', title: 'Only a dream, or a dream and a plan?',
        left: { label: 'Only a positive dream', items: ['Everything will fall into place by itself.', 'Tomorrow I will be a completely different person.', 'Obstacles? No need to think about them.'] },
        right: { label: 'Dream + obstacle + plan', items: ['My wish: a short walk every day this week.', 'My obstacle: evening tiredness and the thought “I’ll do it tomorrow.”', 'If I am tired, then I will walk for just 10 minutes.'] },
        note: 'Mental contrasting and if–then planning together showed a small-to-medium average effect; this short lesson has not been tested separately.' },
      deeper: [
        { heading: 'Why a plan works better than willpower in the moment', paragraphs: [
          'An if–then plan hands a decision to your past self. At noon, calm and clear-headed, you decide what you will do at six o’clock when you are tired. When six o’clock comes, you do not have to negotiate with yourself; the cue (“I feel tired”) is already linked to a small action (“ten minutes only”). This is why the “if” part works best when it is specific: a time, a place or a feeling you can recognize.',
          'A good plan is also small enough to survive a bad day. “If I’m tired, I’ll do the whole workout anyway” is a promise to a version of you who is not tired. “If I’m tired, I’ll do the two-minute version” is a plan for the person who will actually be there.',
        ] },
        { heading: 'Commitment devices: making your plan harder to drop', paragraphs: [
          'A commitment device is a choice you make now that makes it harder for your future self to back out. It can be soft, like telling a friend, or firm, like putting money on the line. In one field experiment, smokers were offered a savings account: they deposited money for six months and then took a nicotine test. If they passed, the money came back; if not, it went to charity. Only 11% of those offered it signed up, but the group offered the account was 3 percentage points more likely to pass the test, and the difference held at surprise tests a year later.',
          'That is a small effect with low take-up, which is an honest picture: commitment devices help some people, some of the time. The fresh-start study found that new commitments on stickK, a website where people sign such contracts, rose at the start of each week and even more at the start of a year. If you like the idea, start with the softest version that still feels real to you.',
        ],
          visual: { kind: 'table', title: 'Commitment devices, from soft to firm', columns: ['Type', 'Example', 'What it costs to back out'],
            rows: [
              ['Word', 'Tell one supportive person what you will do and when', 'A slightly awkward conversation'],
              ['Friction', 'Put the tempting app in a folder on your last phone screen for a week', 'A few extra taps'],
              ['Pre-payment', 'Book and pay for a class in advance', 'Losing the fee'],
              ['Contract', 'Money you lose if you do not follow through', 'Losing the deposit'],
            ],
            note: 'Firmer is not always better: choose a device you would be glad to have chosen, and never one that could harm you or someone else.' } },
      ],
      example: { title: 'Marcus, 41, warehouse supervisor', text: 'Marcus chose health that morning: a short walk after work. At lunch, walking to the sandwich shop, he asked himself what would actually stop him. The honest answer was not rain or time. It was the couch, and the thought “I’ve earned a rest.” He typed into his phone: “If I sit down on the couch before walking, then I’ll stand up and walk just to the corner and back.” It felt almost too small to count. At 6:15 he did sit down, and the thought came right on cue. He remembered the note, grumbled, and walked to the corner. Then he kept going for twelve minutes. The next day he did not go past the corner, and he let that count too.' },
      technique: { name: 'WOOP', origin: 'Gabriele Oettingen · Rethinking Positive Thinking (2014)',
        steps: [
          'Set aside a few calm minutes and silence your phone.',
          'Wish: in a few words, write a wish for today or this week that is challenging but reachable.',
          'Outcome: picture vividly the best outcome you will experience when this wish comes true.',
          'Obstacle: find the main obstacle inside you that could stop you, and picture it just as vividly.',
          'Plan: write the sentence “If [obstacle] happens, then I will [action].”',
          'Read the plan once more shortly before the time the obstacle is likely to appear.',
        ],
        evidence: 'Using mental contrasting and if–then planning together showed a small-to-medium average effect on reaching goals in a meta-analysis. The effect varies by person and goal; WOOP is not a guarantee of results but a thinking tool that makes it easier to see the obstacle in advance.',
        sourceId: 'oettingen-woop-method' },
      photo: { id: '1740815897057-a93a8cf98a70', alt: 'Woman walking along a tree-lined path in a park' } },
    { id: 'turning-day-3', title: 'Afternoon · First evidence: confidence follows the step', minutes: 8,
      goal: 'This afternoon, take a two-minute first step in the area you chose and record it as the first evidence for your confidence.',
      reading: ['In 1977 psychologist Albert Bandura introduced the idea of self-efficacy: your belief that you can do a particular thing. According to Bandura, this belief has four sources: your own experiences of success, watching others, encouraging words, and the state of your body. The most powerful is your own success, because it rests directly on what you lived through. So instead of waiting for confidence to arrive, you can produce a small success yourself today.', 'In Stajkovic and Luthans’s meta-analysis of 114 studies and 21,616 people, self-efficacy and work performance showed a moderate relationship (r = 0.38). This is a relationship; on its own it does not show which causes which, or by how much, and it comes from workplaces. Bandura also writes that a belief strengthened by repeated success is shaken less by occasional setbacks. So today’s goal is not a big achievement but a small, real piece of “I did it” evidence.'],
      practice: ['Decide on the smallest first step in your area that can be finished in two minutes.', 'Set a timer for two minutes and do the step now, without waiting for it to be perfect.', 'When you finish, write “Today I …” and keep it as evidence for your confidence.'],
      reflection: 'After taking the first step, what changed in how you see yourself, even a little?',
      question: 'According to Bandura, what feeds self-efficacy most strongly?',
      options: ['Waiting until you feel completely ready.', 'Small experiences of success that you lived yourself.', 'Only hearing praise from others.'], correct: 1,
      feedback: 'Bandura sees mastery experiences as the most powerful source. Praise and watching others can help too, but the small thing you did yourself is the firmest evidence.',
      takeaway: 'Confidence follows the step you have taken.',
      sources: ['bandura-self-efficacy', 'self-efficacy-work-meta', 'clear-two-minute-rule'],
      visual: { kind: 'table', title: 'The four sources of self-efficacy and how to use them today', columns: ['Source', 'How you can use it today'],
        rows: [
          ['Mastery experience', 'Take the two-minute first step and write it down'],
          ['Watching others', 'Look at the story of someone like you who has walked this path'],
          ['Encouraging words', 'A short supportive sentence from someone you trust, or from yourself'],
          ['Body state', 'Take a few slow breaths before you begin; notice nerves as a normal reaction'],
        ],
        note: 'Bandura treats mastery experience as the most powerful source. This table is not a treatment plan.' },
      deeper: [
        { heading: 'Why small wins count', paragraphs: [
          'It is tempting to wave a two-minute step away: “That doesn’t count, anyone could do that.” But self-efficacy is not built on how impressive a step looks; it is built on the experience of deciding to do something and then doing it. Each time that happens, you collect a small, specific piece of evidence against the story “I never follow through.”',
          'Writing the step down matters because memory is unfair. On a hard evening you will easily recall what went wrong and forget what went right. A written “Today I…” is harder to argue with. Over days, the notes form a record that your belief can lean on.',
        ],
          visual: { kind: 'cycle', title: 'The small-evidence loop', center: 'Self-efficacy',
            nodes: [
              { label: 'Small step', text: 'A two-minute action you can finish.' },
              { label: 'Evidence', text: 'You write down what you did.' },
              { label: 'Belief', text: '“I can do this kind of thing” grows a little.' },
              { label: 'Next step', text: 'Tomorrow’s step feels slightly less heavy.' },
            ],
            note: 'An illustration of Bandura’s idea of mastery experience, not a measured effect.' } },
        { heading: 'Common mistakes', paragraphs: [
          'Making the first step too big is the most common one. If the step needs a good mood, a free hour or perfect conditions, it is not a first step yet. Shrink it until it would be hard to say no to it.',
          'Another mistake is treating the two-minute limit as a rule you must stop at, or as a target you must exceed. Both are fine: if you want to keep going, keep going; if you want to stop, stop. The only job is to start, and to notice that you did.',
        ] },
      ],
      example: { title: 'Priya, 27, junior graphic designer', text: 'Priya had chosen learning: she wanted to get better at hand lettering, but every time she thought about it she pictured a finished poster and felt behind. At 3 p.m., between client files, she set a two-minute timer and wrote one line of letters on a scrap of paper. They were wobbly. When the timer went off she stopped, and wrote in her notes app: “Today I practiced lettering for two minutes.” It looked a bit ridiculous on the screen. But that evening, when her usual thought came (“you never stick with hobbies”), she had a small, specific answer to it. The next afternoon, starting felt a little easier, and she did five minutes.' },
      technique: { name: 'The two-minute rule', origin: 'David Allen · Getting Things Done; James Clear · Atomic Habits (2018)',
        steps: [
          'Write down the behavior you want in your chosen area, for example walking regularly.',
          'Shrink it to a start that takes two minutes, such as putting on your shoes and stepping out the door.',
          'Set a timer for two minutes and do only this small start.',
          'When the time is up, continue if you want to; stopping also follows the rule.',
          'Note what you did as evidence; what matters is not the amount but that you started.',
        ],
        evidence: 'The two-minute rule itself is a practical suggestion rather than a directly tested method. The idea that small, achievable steps can feed self-efficacy fits Bandura’s view of mastery experience, but on its own it does not guarantee reaching a big goal.',
        sourceId: 'clear-two-minute-rule' },
      photo: { id: '1758854486305-eb7621f1e2e4', alt: 'Person working at a table beside a large arched window' } },
    { id: 'turning-day-4', title: 'Late afternoon · Set up your space, tell one person', minutes: 7,
      goal: 'In the late afternoon, make tomorrow’s step easier through your surroundings and tell one supportive person about your decision.',
      reading: ['In a study where Lally and colleagues followed 96 volunteers for 12 weeks, repeating a behavior every day in the same context made it steadily more automatic. Context means the same time, the same place or the same action just before. So to remember tomorrow’s step, you can rely on your surroundings instead of your willpower: put your sneakers by the door, leave the book on your pillow. The more visible and easy the step is, the less effort it takes to begin on a tired day.', 'In Harkin and colleagues’ meta-analysis of 138 experimental studies, monitoring progress showed an average benefit for reaching goals (d = 0.40). The benefit was larger when results were reported to someone else or made public, and when they were physically recorded. That does not mean you have to announce it to everyone; telling one supportive person who will not judge you may be enough. You do not have to share private notes, and because this result pools very different goals, it may be different for you.'],
      practice: ['Put one item you need for tomorrow’s first step somewhere visible right now.', 'Attach your new step to something you already do every day and write it as one sentence.', 'Tell one supportive person about your decision and say you will let them know how it went in a week.'],
      reflection: 'What is the smallest change to your surroundings that would make this step easier tomorrow?',
      question: 'In Harkin’s 2016 meta-analysis, when was the effect of monitoring progress larger?',
      options: ['When results were only kept in mind without telling anyone.', 'When results were reported or shared and physically recorded.', 'When no monitoring was done and only a goal was set.'], correct: 1,
      feedback: 'The effect was larger when results were reported or made public and physically recorded. Sharing is still optional; one person who supports you can be enough.',
      takeaway: 'An easy environment and one supporter take weight off your willpower.',
      sources: ['habits', 'monitoring', 'fogg-anchor-recipe'],
      visual: { kind: 'compare', title: 'A hard environment or an easy one?',
        left: { label: 'Makes the step harder', items: ['Sneakers at the back of the closet', 'Book on the shelf, phone next to the pillow', 'No one knows about your decision'] },
        right: { label: 'Makes the step easier', items: ['Sneakers ready by the door', 'Book on the pillow, phone in another room', 'A supportive person will ask in a week'] },
        note: 'Sharing is optional; you do not have to tell anyone you think would judge you.' },
      deeper: [
        { heading: 'Why your surroundings do some of the work', paragraphs: [
          'Willpower is least available exactly when you need it: at the end of a long day, when you are hungry, tired or low. Your surroundings, on the other hand, are there all the time. A cue you can see (shoes by the door) reminds you without effort, and a step that is already half set up asks for less of the energy you do not have.',
          'The same logic runs in reverse. Most of us do not choose to scroll for an hour; the phone is simply closer than the book. You do not need to become a different person to change that. Moving one object tonight is often easier than making one big decision tomorrow.',
        ],
          visual: { kind: 'steps', title: 'Set up tomorrow’s step tonight',
            steps: [
              { label: 'Pick the moment', text: 'When exactly will tomorrow’s step happen? After coffee, after work, before bed.' },
              { label: 'Place the cue', text: 'Put the item you need where your eyes will fall at that moment.' },
              { label: 'Remove one hurdle', text: 'Lay out the clothes, open the file, fill the water bottle.' },
              { label: 'Move one temptation', text: 'Put the thing that usually pulls you away one room further.' },
            ],
            note: 'Four small moves, a few minutes tonight. None of them requires motivation tomorrow.' } },
        { heading: 'Choosing the right person to tell', paragraphs: [
          'The research finding is about reporting progress, not about seeking applause. The most useful person is someone who will simply ask, “So how did it go?” and listen to either answer. A friend who would tease you, compete with you or turn your plan into their project is not a good fit for this step.',
          'Keep the message short and specific: what you are doing, when, and when you will report back. “I’m walking ten minutes after work this week; can I tell you on Sunday how it went?” is enough. If there is truly no one right now, a written weekly note to yourself still counts as a physical record.',
        ] },
      ],
      example: { title: 'Tomás, 52, high-school teacher', text: 'Tomás wanted to read before bed instead of scrolling. At 5 p.m., before grading, he took the novel from the living-room shelf and put it on his pillow. He moved his phone charger to the kitchen, which felt oddly dramatic. Then he wrote his recipe on a sticky note: “After I brush my teeth, I’ll read one page.” Finally he texted his brother, who had once read the same book: “Trying to read a page every night this week. I’ll tell you Sunday how far I got.” His brother answered with a thumbs-up and nothing else, which was exactly right. That night, the book was simply there, and the phone was not.' },
      technique: { name: 'The anchor and tiny-behavior recipe', origin: 'BJ Fogg · Tiny Habits (2019)',
        steps: [
          'Choose something you already do reliably every day; this will be your anchor.',
          'Shrink your new behavior until it takes 30 seconds.',
          'Write your recipe: “After I [anchor], I will [tiny behavior].”',
          'As soon as you do the tiny behavior, give yourself a short, sincere celebration, like a smile or a quiet “Nice!”',
          'Repeat the recipe tomorrow with the same anchor; if it does not stick, change the anchor or the size of the behavior.',
        ],
        evidence: 'The idea that repeating a behavior in the same context increases automaticity fits the findings of Lally and colleagues. The Tiny Habits method itself, especially the celebration step, has had limited testing in independent studies; try it as a suggestion.',
        sourceId: 'fogg-anchor-recipe' },
      photo: { id: '1756312177615-e153c9db507d', alt: 'Woman talking on the phone in a kitchen' } },
    { id: 'turning-day-5', title: 'Night · Write down the evidence, prepare tomorrow', minutes: 8,
      goal: 'At night, write down the day’s evidence, look kindly at what went wrong, and make tomorrow’s first step clear.',
      reading: ['In the daily scheme described in his autobiography, Benjamin Franklin opens the morning with the question “What good shall I do this day?” and closes the evening with “What good have I done today?” The evening question is a simple way to end the day with evidence rather than flaws. Writing down the small step you took, the space you set up or the person you talked to becomes a concrete record your confidence can rest on. If something went wrong, you can note that too, without judgment, as information.', 'In a study of 119 students by Wohl and colleagues, those who forgave themselves more for procrastinating on the first exam procrastinated less before the second; this finding is correlational, not experimental. Self-compassion interventions also showed small-to-medium reductions in stress and anxiety symptoms across 56 randomized trials. In a lab study by Scullin and colleagues with 57 young adults, those who spent 5 minutes before bed writing a specific to-do list fell asleep faster than those who wrote about completed tasks. So the night’s order is: a kind review, tomorrow’s one first step, then rest.'],
      practice: ['Answer Franklin’s evening question and write today’s evidence as “Today I …”.', 'If something went wrong, write yourself the kind sentence you would say to a friend in the same situation.', 'Write tomorrow’s first step in one line with a time and a place, and add it to your evidence page in the app.'],
      reflection: 'What small piece of evidence about yourself did you collect today?',
      question: 'After a setback, which inner voice fits this lesson better?',
      options: ['“I messed up again; this is just how I am.”', '“Today didn’t go to plan; I saw what made it hard, and tomorrow I’ll shrink the step and try again.”', '“I’ll act as if nothing happened and not think about it.”'], correct: 1,
      feedback: 'Forgiving yourself does not mean ignoring the setback; it means seeing it without judgment and trying again. The correlational finding by Wohl and colleagues suggests this attitude goes together with less procrastination on the next attempt.',
      takeaway: 'Close the day with evidence; open tomorrow with one step.',
      sources: ['franklin-daily-questions', 'self-forgiveness', 'self-compassion', 'todo-list-bedtime', 'murphy-subconscious'],
      visual: { kind: 'table', title: 'Closing the night: four short questions', columns: ['Question', 'Sample answer'],
        rows: [
          ['What good have I done today?', 'I walked for two minutes and put my sneakers by the door.'],
          ['What made it hard?', 'Afternoon tiredness; my if–then plan worked.'],
          ['My kind sentence to myself', 'I started; it is a small but real step.'],
          ['Tomorrow’s first step', 'In the morning after coffee, a 10-minute walk from my front door.'],
        ],
        note: 'In one small lab study, a specific to-do list was linked to falling asleep faster. If your thoughts start racing, stop writing and return to rest.' },
      deeper: [
        { heading: 'Designing tomorrow as a realistic ideal day', paragraphs: [
          'Franklin did not only ask his two questions; he laid out his whole day hour by hour, with time for work, meals, reading and rest. You do not need a schedule that detailed. But spending a minute tonight picturing a realistic ideal day (not a perfect one) helps you see where tomorrow’s step fits and what might crowd it out.',
          'A useful ideal day has only a few fixed points: the one step for your chosen area, one moment of rest, and one moment of connection with another person. Everything else can stay flexible. If you design a day that only works when nothing goes wrong, you have designed a day that will not happen; leave space for the unexpected.',
        ],
          visual: { kind: 'table', title: 'A realistic ideal day: three anchors', columns: ['Anchor', 'When', 'Example'],
            rows: [
              ['Your one step', 'Tied to something you already do', 'After morning coffee: a 10-minute walk'],
              ['Rest', 'A protected pause', 'Lunch away from the screen'],
              ['Connection', 'A short, real contact', 'Text or call one person in the evening'],
            ],
            note: 'Three fixed points and plenty of slack. This is a planning aid, not a rule for how your day must go.' } },
        { heading: 'Kindness is not letting yourself off the hook', paragraphs: [
          'Some people fear that being kind to themselves will make them lazy. The research in this lesson points the other way, though cautiously: in the Wohl study, students who forgave themselves more procrastinated less the next time, and the link was explained by less negative feeling about the task. Self-criticism makes the task feel worse, and a task that feels worse is easier to avoid.',
          'A kind review still names what happened. “I skipped the walk because I stayed late at work” is honest. Adding “and that makes sense; tomorrow I’ll do the corner-and-back version” is kind. Leaving out the first half would be avoidance; leaving out the second half would be harshness.',
        ] },
      ],
      example: { title: 'Aisha, 38, accountant and parent of two', text: 'Aisha had planned a ten-minute stretch after lunch, but a client call ran long and she forgot until bedtime. Her first thought, brushing her teeth, was “Day one and I already failed.” She sat on the edge of the bed with her notebook instead. Under “What good have I done today?” she wrote: “Put the yoga mat by the desk. Told Sam about my plan.” Under “What made it hard?”: “The call ran over; stretching after lunch depends on the calendar.” Her kind sentence: “Of course it slipped on a busy day; I still set things up.” Tomorrow’s step: “7:30 a.m., before the kids wake up, three minutes on the mat.” She closed the notebook and turned off the light.' },
      technique: { name: 'A calm suggestion before sleep', origin: 'Joseph Murphy · The Power of Your Subconscious Mind (1963)',
        steps: [
          'Lie down, dim the lights and relax your body with a few slow breaths.',
          'Turn a single intention for tomorrow into a short, positive, doable sentence, such as “Tomorrow after coffee, I go for a walk.”',
          'As sleep grows heavier, repeat this sentence slowly to yourself a few times, without forcing it, like a lullaby.',
          'See yourself doing the step as a short scene and notice the calm.',
          'If your mind drifts into worry, let the sentence go and simply return to your breath.',
        ],
        evidence: 'Putting tomorrow’s step into a clear sentence before bed and rehearsing it calmly may help you prepare; writing a specific to-do list was linked to falling asleep faster in one small study. The claim that the subconscious will bring the desired outcome, money or healing on its own is not supported by science; what decides the outcome is the step you take the next day.',
        sourceId: 'murphy-subconscious' },
      photo: { id: '1768219565623-501f93ae384b', alt: 'Desk lit by a lamp in the evening' } },
    { id: 'turning-day-6', title: 'The next 7 days · Turn the beginning into evidence', minutes: 9,
      goal: 'For the next 7 days, repeat the same small step daily, track it, return right away after a missed day, and look back on day 7.',
      reading: ['A single day does not change your life, but it can turn a beginning into a repeated behavior. In the study by Lally and colleagues, the time it took for a behavior to reach a high level of automaticity ranged from 18 to 254 days, depending on the person. So 7 days is a reasonable span not for a habit, but for a first run of evidence. In the same study, missing a single opportunity did not noticeably disrupt habit formation. If you miss a day, nothing is over.', 'In Harkin and colleagues’ meta-analysis, monitoring progress showed an average benefit for reaching goals, and the effect was larger when the information was physically recorded. This week, do the same small step every day and mark it; you can write it on the Today screen in the app as the day’s one decision. If you miss a day, do only the smallest version the next day: the rule is “never miss twice in a row.” On day 7, in a weekly look back, choose what worked and what you will shrink.'],
      practice: ['Draw seven boxes on a calendar or a sheet of paper and tick one each day you take the step.', 'Write now, in one sentence, the smallest version you will do if you miss a day.', 'Put a ten-minute look-back on day 7 into your calendar now.'],
      reflection: 'After 7 days, what sentence about yourself would you like to be able to say with evidence?',
      question: 'According to this lesson, what should you do when you miss a day?',
      options: ['The chain is broken; I should start over with a bigger goal.', 'Do the smallest version of the step the next day and focus on never missing twice in a row.', 'Wait for the next Monday or the first of the month to start again.'], correct: 1,
      feedback: 'In the study by Lally and colleagues, missing a single opportunity did not noticeably disrupt habit formation. What matters is coming back quickly; you do not need a special day on the calendar to start again, and tomorrow can be a beginning too.',
      takeaway: 'One day starts it; repeated days prove it.',
      sources: ['habits', 'monitoring', 'seinfeld-chain-story', 'fresh-start-framing'],
      visual: { kind: 'steps', title: 'A one-week evidence loop',
        steps: [
          { label: 'Do', text: 'Take the same small step with the same anchor or at the same time.' },
          { label: 'Mark', text: 'Tick that day’s box on the calendar or in the app.' },
          { label: 'If it gets hard', text: 'Go back to your if–then plan or shrink the step.' },
          { label: 'If you miss', text: 'Do the smallest version the next day; never miss twice in a row.' },
          { label: 'Day 7', text: 'Look back: what worked, what will you change, will you continue?' },
        ],
        note: 'Seven days is a span for a first run of evidence, not for a habit to settle; in the study by Lally and colleagues that took from 18 to 254 days depending on the person.' },
      deeper: [
        { heading: 'Fresh starts are renewable', paragraphs: [
          'The fresh-start research carries a quiet lesson for the week ahead: a beginning does not have to come from the calendar. In the 2015 experiments, simply calling an ordinary day a beginning raised people’s wish to start. You can use that on purpose. After a missed day, tomorrow morning is a perfectly good landmark; so is the start of the next week, or the day you finish a hard project.',
          'What does not help is using the next landmark as a reason to wait. “I’ll restart on Monday” on a Wednesday gives away four days. A better use is “Tomorrow is day one of the second half of my week.” The line between old and new can be drawn wherever you need it.',
        ] },
        { heading: 'Your day-7 look back', paragraphs: [
          'On day 7, look at the boxes without grading yourself. A week with four ticks and three gaps is not a failed week; it is data about when the step fits your life and when it does not. The questions below take about ten minutes. Answer them in writing if you can, because a physical record was linked to a larger benefit in the monitoring research.',
          'Then choose one of three paths: keep the step as it is, shrink it, or change the anchor or time. Adding more is also an option, but only if the current step has started to feel easy. The aim for the second week is the same as for the first: small enough to repeat.',
        ],
          visual: { kind: 'table', title: 'Day-7 questions', columns: ['Question', 'What it tells you'],
            rows: [
              ['On which days did it happen easily?', 'The conditions that support your step'],
              ['On which days did it slip, and why?', 'The obstacle your next if–then plan should target'],
              ['Did I come back after a missed day?', 'Whether your smallest version is small enough'],
              ['Keep, shrink or change?', 'Your plan for the next seven days'],
            ],
            note: 'A look back is for learning, not for grading. Gaps are information.' } },
      ],
      example: { title: 'Jonah, 23, delivery driver studying part time', text: 'Jonah’s step was twenty minutes of accounting review after dinner. He drew seven boxes on the back of an envelope and stuck it on the fridge. Monday and Tuesday got ticks. On Wednesday he worked late and the envelope stayed empty, and he felt the familiar urge to “start fresh next week.” Instead he looked at the sentence he had written on day one: “If I miss, I do five flashcards.” On Thursday he did five flashcards, then eight. By Sunday he had five ticks out of seven. In his look back he noticed that both gaps were late-shift days, so for week two he moved the step to his lunch break on those days.' },
      technique: { name: 'Don’t break the chain, never miss twice', origin: 'Story attributed to Jerry Seinfeld (as told by Brad Isaac) · retold by James Clear and in Atomic Habits (2018)',
        steps: [
          'Hang a calendar you will see every day on the wall or desk, or draw seven boxes on paper.',
          'On each day you take your small step, put a big X or a tick over that day.',
          'After a few days, notice the chain forming and make keeping it going your daily goal.',
          'If you miss a day, do not punish yourself; do the smallest version of the step the next day.',
          'Set your rule as “never miss two days in a row,” and on day 7 look at the chain and update your plan.',
        ],
        evidence: 'The story is an anecdote; according to James Clear’s note, Seinfeld has said the idea was not his and that he did not claim to use it. Tracking progress in writing showed an average benefit in a meta-analysis, and missing a single day did not noticeably disrupt habit formation; the chain is a tool, not a demand for perfection.',
        sourceId: 'seinfeld-chain-story' },
      photo: { id: '1529651737248-dad5e287768e', alt: 'Pen resting on a planner calendar' } },
  ],
};
